// Written by the T9 test directly through the REST API (not by the AI).
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"
#include <stdio.h>
void app_main(void) {
    gpio_reset_pin(4);
    gpio_set_direction(4, GPIO_MODE_OUTPUT);
    printf("T9 external firmware: 300 ms on / 300 ms off on GPIO4\n");
    int v = 0;
    while (1) { v = !v; gpio_set_level(4, v); vTaskDelay(pdMS_TO_TICKS(300)); }
}
